            "duration": "Одна ніч або до завершення",
            "text": "Ви віддаєте простий усний наказ одним реченням тварині, яку бачите в межах Короткої Дистанції. Тест Здібності потрібен лише тоді, коли ціль — гуль, фамулус або інша тварина, надприродно пов’язана з надприродною істотою, якою не є ви. У такому разі виконайте Тест Здібності проти Рішучості цілі.\n\nТварина виконує наказ буквально й не здатна тлумачити або виводити прихований зміст. Якщо ви вмієте говорити з тваринами, можете висловитися зрозуміліше, що дозволяє дати трохи складніший наказ, який потребує певного тлумачення або містить додаткову умову. Наприклад, якщо ви не можете говорити з твариною, можете наказати їй охороняти місце, і вона атакуватиме всіх, крім вас, хто туди ввійде. Якщо можете говорити з твариною, можете наказати їй охороняти місце, але пропускати тих, хто має певний запах, несе певний предмет або наспівує конкретну мелодію. Наказ не може змусити ціль завдати шкоди самій собі або наразити себе на безпосередню небезпеку.\n\n[Дозрівання]. Коли у вас стає більше ніж 1 точка в цій Дисципліні, ви можете використовувати цю Здібність по-новому:\n\n●●: За кожну точку в цій Дисципліні ви можете одночасно наказати ще 3 тваринам із родини цільової тварини (наприклад, псовим, вороновим, котячим або мишевим). Якщо тест потрібен, ви виконуєте його проти найсильнішого члена групи. Усі цілі отримують однаковий наказ.\n\n●●●●●: Ви можете наказати цілій зграї, стаду або подібній сукупності не пов’язаних між собою тварин, виконуючи тест, якщо він потрібен, проти найсильнішого члена. Ваш наказ може змусити ціль або цілі завдати шкоди самим собі чи наразити себе на безпосередню небезпеку."
