            "text": "Ви імітуєте поклик конкретної тварини, прикликаючи істот цього виду до себе. Тварини цього виду в межах Дистанції можуть відгукнутися на поклик і прибути так швидко, як можуть.\n\nКоли ви використовуєте цю Здібність, виконайте Тест Здібності зі Складністю, що дорівнює Самовладанню найближчої тварини цього виду. Кількість Успіхів визначає, скільки тварин відгукнуться. Якщо в межах Дистанції немає достатньо тварин цього виду, приходять усі наявні; якщо немає жодної, Здібність не має ефекту.\n\n1 Успіх: Відгукується одна тварина цього виду в межах Дистанції.\n\n2 Успіхи: Відгукується чверть тварин цього виду в межах Дистанції.\n\n3 Успіхи: Відгукується половина тварин цього виду в межах Дистанції.\n\n4 Успіхи: Відгукується більшість тварин цього виду в межах Дистанції.\n\n5 Успіхів: Відгукуються всі тварини цього виду в межах Дистанції.\n\n[Дозрівання]. Коли у вас стає більше ніж 2 точки в цій Дисципліні, ви можете використовувати цю Здібність по-новому:\n\n●●●: Ви можете одночасно прикликати 2 види тварин.\n\n●●●●: Ви можете одночасно прикликати 4 види тварин.\n\n●●●●●: Ви можете одночасно прикликати всіх тварин у межах Дистанції."
