            "text": "Ви єднаєтеся зі своїм Звіром і набуваєте форми добре знайомої вам тварини, приблизно вашого розміру. У тваринній формі ви зберігаєте всі звичайні характеристики, але отримуєте +2 кубики до тестів, у яких обрана тварина мала б перевагу, наприклад до вистежування здобичі у формі вовка. У тваринній формі ви не можете говорити й не можете використовувати Соціальні або Ментальні Здібності Дисциплін, якщо ціль не є твариною вашого виду. Якщо у вас є Кланова Риса Дикі Шепоти, ви можете говорити з тваринами, перебуваючи у тваринній формі.\n\nВи знаєте кількість тваринних форм, що дорівнює вашим точкам у цій Дисципліні, і можете набувати лише їх. Щоб змінити відомі форми, ви мусите випити кров нової тварини, на яку хочете перетворюватися, й під час денного спокою медитувати над її смаком, формою, запахом і загальною тілесністю. Одночасно ви обираєте одну зі своїх інших відомих форм і забуваєте її.\n\n[Дозрівання]. Коли у вас стає більше ніж 3 точки в цій Дисципліні, ви можете використовувати цю Здібність по-новому:\n\n●●●●: Ви також можете набувати форми тварини розміром від половини до півтора вашого розміру.\n\n●●●●● ●: Ви також можете набувати форми тварини розміром від чверті до подвійного вашого розміру.\n\n●●●●● ●●●: Ви можете набувати форми будь-якої тварини, чию кров куштували."
