            "distance": "Коротка",
            "duration": "Одна Сцена",
            "text": "Ви накладаєте на ціль надприродну мітку, через яку вона привертає ворожу увагу всіх тварин поблизу. Тварини нападають на ціль і дошкуляють їй, заважаючи кожній дії та відволікаючи її.\n\nКоли ви використовуєте цю Здібність, мусите успішно виконати Тест Здібності проти Самовладання цілі. Кількість Успіхів визначає, скільки тварин з’явиться, щоб переслідувати ціль, і наскільки сильно вони на неї вплинуть. Якщо поблизу немає тварин, Здібність не має ефекту. Ціль зазнає ефектів, доки Здібність не завершиться, тварини не втратять змогу дістатися до цілі або не підуть чи не загинуть.\n\n1: Відгукується одна тварина. Ціль отримує штраф -1 кубик до всіх тестів.\n\n2: Як за 1 Успіх, але відгукується чверть тварин у межах Дистанції, а штраф збільшується до -2.\n\n3: Як за 2 Успіхи, але відгукується половина тварин у межах Дистанції. Крім того, на початку кожного ходу цілі тварини атакують її, завдаючи шкоди, що дорівнює половині ваших точок у цій Дисципліні.\n\n4: Як за 3 Успіхи, але відгукується більшість тварин у межах Дистанції, а шкода дорівнює вашим точкам у цій Дисципліні.\n\n5: Як за 4 Успіхи, але відгукуються всі тварини в межах Дистанції, а штраф збільшується до -3.\n\n[Дозрівання]. Коли у вас стає більше ніж 3 точки в цій Дисципліні, ви можете використовувати цю Здібність по-новому:\n\n●●●●●: Ви можете застосувати цю Здібність до кількості цілей, що дорівнює половині ваших точок у цій Дисципліні.\n\n●●●●● ●●: Ви можете застосувати цю Здібність до будь-якої кількості цілей у межах Дистанції."
