        "text": "Як Романтик, ви відчуваєте, що існування приносить задоволення лише тоді, коли ви когось любите й отримуєте любов у відповідь. Вас легко зачаровують зовнішність, особистість або вчинки інших, і ви часто уявляєте романтичні стосунки там, де їх немає. Коли ваші почуття взаємні, це підносить вас; коли ні — може занурити в глибокий смуток.\n\nПотурання. Ви намагаєтеся справити враження на інших і створити з ними зв’язок, особливо з тими, хто пробуджує у вас романтичний інтерес. Ви ризикуєте заради цього інтересу. Витрачаєте більше часу, ніж слід, мріючи про стосунки. Нехтуєте обов’язками, щоб бути поруч із тим, кого любите.\n\nСпалах Романтика: Романтична Жертва. Значення має лише любов, і навіть власне існування може бути гідною жертвою заради неї. Ви не можете використовувати Ментальні Здібності Дисциплін і мусите робити все можливе, щоб захищати, вражати або допомагати об’єкту романтичного інтересу. Ви отримуєте бонус до кубиків, що дорівнює вашому Модифікатору Покоління, на всі тести, спрямовані на захист або допомогу цій особі. Бонус подвоюється, якщо така Дія наражає вас на небезпеку або ставить під загрозу те, що ви спочатку збиралися зробити. Усі тести, не пов’язані з такими діями, отримують штраф до кубиків, що дорівнює подвоєному Модифікатору Покоління."
