            "text": "Тіні згущуються довкола вас, даючи бонус, що дорівнює вашому Модифікатору Покоління, до тестів, пов’язаних із хованням або крадькома пересуватися, а також до тестів на залякування чи примушування смертних.\n\nАктивація. Коли ви виконуєте такий тест, можете реакцією активувати цю [Рису] для Базового Успіху."
