            "text": "Ви можете наказувати найближчим тіням у межах Короткої Дистанції виконувати прості Дії, наприклад відчиняти двері або тягнути важелі. Ці тіні можуть робити все, що можна виконати Малою Дією, але не можуть активувати Здібності Дисциплін або виконувати настільки складні завдання, як набір тексту чи керування транспортом. Ви не можете використовувати ефекти цієї [Риси], якщо цільова зона або предмет перебувають під яскравим світлом."
