            "text": "Коли ви використовуєте Здібність Домінування проти цілі, яка зазнає ефекту однієї з ваших Здібностей Розбещення або перебуває в тіні чи темряві, ви отримуєте бонус до Тесту Здібності, що дорівнює вашому Модифікатору Покоління."
