        "id": "nosferatu",
        "name": "Nosferatu",
        "description": "Клан таємниць, інформації та скритності. Вони не можуть приховати свою потворну природу так, як інші вампіри, зате є майстрами приховувати все інше й знаходити те, що приховують усі інші.",
