            "text": "Ви можете використати надприродну енергію, що живить ваше приховування, для посилення власної сили. Коли ви використовуєте Здібність Могутності під дією Здібності Затемнення, можете негайно завершити дію Затемнення й додати свої точки в Затемненні до будь-якого тесту, що є частиною цієї Здібності Могутності."
