            "prerequisites": "Неонат або сильніший. Щонайменше 2 точки в Присутності.",
            "text": "Коли ви використовуєте Здібність Присутності, можете витратити 1 Силу Волі додатково до звичайної вартості Здібності, щоб передати її через електронний пристрій. Ви можете впливати на цілі, які бачать або чують вас, за умови що вони дивляться чи слухають пряму трансляцію, а не запис. Якщо Здібність впливає лише на одну ціль, ви мусите назвати її, хоча це може бути онлайн-ім’я або подібний ідентифікатор, обраний самою ціллю, а не її справжнє ім’я. Якщо Здібність впливає на всі цілі в межах визначеної Дистанції, цілі випадково обираються серед тих, хто вас бачить або чує, до максимуму 5 цілей за кожну вашу точку в Присутності."
