            "text": "Ваші чарівливі сили тепер можна передавати через предмети. Ви можете торкнутися предмета й наситити його Здібністю Присутності рангу 3 або нижче. Наступного разу, коли до нього торкнеться істота, яка не є твариною, Здібність активується так, наче ви щойно застосували її до цієї істоти. Ви знаєте, коли Здібність активовано. Якщо вона потребує тесту, ви виконуєте його в момент активації істотою. На розсуд Оповідача деякі Здібності Присутності можуть не підходити для використання з цією [Рисою]. Наприклад, Друзі у Вороги навряд чи добре працюватиме, якщо закласти її в диван, але портрет із вашим зображенням може змусити людину відчути щось подібне до ефектів Кровного Зв’язку."
