            "text": "Жертви ваших Здібностей Домінування вважають, що все зроблене під їхнім впливом було наслідком власної вільної волі, і захищають та раціоналізують свої вчинки. Близький довірений друг жертви, який наполегливо ставить під сумнів цю раціоналізацію, може спонукати її виконати тест Рішучості зі Складністю, що дорівнює вашим точкам у Домінуванні. У разі Успіху жертва починає сумніватися в собі та власних діях. На розсуд Оповідача жертва, яка кілька разів досягає Успіху в такому тесті, зрештою може почати підозрювати ваше втручання у своє життя, помітивши, що її дивна поведінка часто виникає після взаємодій із вами."
