            "text": "Розуми жертв ваших Здібностей Домінування й Присутності зміцнюються проти впливу подібних сил інших. Ціль, на яку зараз діє одна з ваших Здібностей Домінування або Присутності, отримує бонус кубиків, що дорівнює вашим точкам у Домінуванні або Присутності — залежно від того, що вище, — до захисту від Здібностей Домінування й Присутності інших. Вона також отримує цей бонус проти будь-яких Здібностей, крім ваших, які змусили б її діяти проти власної волі або проти вашої волі, доки вона перебуває під впливом вашої Здібності Домінування чи Присутності."
